def f(n):
    """Calculates the largest odd divisor of n."""
    if n == 0:
        return 0 # Should not happen for positive integers
    while n % 2 == 0:
        n //= 2
    return n

def check_condition(u, v):
    """Checks if f(u+v+k) - f(u+k) is a multiple of 4 for k=0 to v-1."""
    for k in range(v):
        A = u + k
        B = u + v + k

        diff = f(B) - f(A)

        if diff % 4 != 0:
            return False
    return True

